          foundItemTags: result.foundItemTags,
          unlockedSkillIds,
          chapterCompleted: result.chapterCompleted,
          escaped: this.state.escaped,
          roomFeature: cutsceneRoom.feature,
          roomId: cutsceneRoom.roomId
