  function renderCombatSprite(k, spriteName, x, y, options = {}) {
    if (!spriteName) {
      return;
    }
    const scale = options.scale ?? (options.isPlayer ? COMBAT_SPRITE_SCALE + 0.3 : COMBAT_SPRITE_SCALE);
    if (options.showShadow) {
      k.add([
        k.rect(Math.max(18, scale * 18), Math.max(6, scale * 6), { radius: 4 }),
        k.pos(x - Math.max(9, scale * 9), y + Math.max(10, scale * 10)),
        k.color(16, 14, 18),
        k.opacity(0.55),
        UI_TAG
      ]);
    }
    const sprite = k.add([
      k.sprite(spriteName),
      k.pos(x, y),
      k.anchor("center"),
      k.scale(scale),
      UI_TAG
    ]);
    if (options.animate) {
      const baseY = y;
      sprite.onUpdate(() => {
        sprite.pos = k.vec2(x, baseY + Math.sin(k.time() * 4.6) * 2.2);
      });
    }
  }

  // src/panel-formulas.ts
  function infoPanelHeightForLines(lines, compact = true) {
    const header = compact ? 22 : 26;
    const lineHeight = compact ? 14 : 16;
    return header + Math.max(1, lines) * lineHeight + 8;
  }

  // src/ui-selectors.ts
  function selectDialogueSummary(ui2) {
    const last = ui2.dialogue.steps.at(-1);
    return {
      sequence: ui2.dialogue.sequence,
      stepsCount: ui2.dialogue.steps.length,
      lastLabel: last?.label ?? "none",
      lastKind: last?.kind ?? null,
      lastOptionId: last?.optionId ?? null
    };
  }
  function selectRecentDialogueTimeline(ui2, limit = 3) {
    return ui2.dialogue.steps.slice(-Math.max(1, limit)).map((step, idx) => `${idx + 1}. t${step.turn} ${step.label}`);
  }

  // src/scene-blocks.ts
  function buildDialogueProgressBlock(ui2, rect, limit = 3) {
    const summary = selectDialogueSummary(ui2);
    const timeline = selectRecentDialogueTimeline(ui2, limit);
    const lines = [
      { text: `[SEQ] ${summary.sequence} | [STEPS] ${summary.stepsCount}`, tone: "accent" },
      { text: `[LAST] ${summary.lastLabel}`, tone: "good" },
      { text: timeline.join(" | ") || "No dialogue decisions yet.", tone: "neutral" }
    ];
    return {
      kind: "info",
      x: rect.x,
      y: rect.y,
      width: rect.width,
      height: infoPanelHeightForLines(lines.length),
      title: "Progression",
      lines
    };
  }
  function inRuneForgeContext(state) {
    const roomFeature = state.status?.roomFeature;
    if (roomFeature === ROOM_FEATURE_RUNE_FORGE) return true;
    return itemsByActionType(state, ACTION_TYPE.EVOLVE_SKILL).length > 0;
  }
  function hasEncounter(state) {
    const fight = firstItemByActionType(state, ACTION_TYPE.FIGHT);
    return Boolean(fight?.available);
  }

  // src/scene-layout.ts
  function renderSceneLayout(k, layout, state) {
    let y = addHeader(k, layout.width, layout.title, layout.subtitle);
    if (layout.tabs && layout.tabs.length > 0 && state?.activeTab && state.onSelectTab) {
      y = addTabBar(k, PAD, y, layout.tabs, state.activeTab, state.onSelectTab);
      y += 2;
    }
    return y;
  }

  // src/combat-scene.ts
